package io.github.diodeme.ji.extension;

import java.time.Instant;
import java.util.Map;

/** Transport-neutral Tool policy evaluated before permission and again immediately before effect. */
@FunctionalInterface
public interface ToolExecutionPolicy {
    Evaluation evaluate(Context context);

    record Context(String hostId, String sessionId, String actorId, String transport,
                   WorkspaceProvider.WorkspaceIdentity workspace, String toolCallId, String toolName,
                   Map<String, Object> arguments, long operationRevision, Instant evaluatedAt) {
        public Context {
            requireText(hostId, "hostId");
            requireText(sessionId, "sessionId");
            requireText(actorId, "actorId");
            requireText(transport, "transport");
            requireText(toolCallId, "toolCallId");
            requireText(toolName, "toolName");
            if (workspace == null || evaluatedAt == null) throw new IllegalArgumentException("policy fields must not be null");
            arguments = Map.copyOf(arguments);
            if (operationRevision < 0) throw new IllegalArgumentException("operationRevision must be non-negative");
        }
    }

    record Evaluation(Action action, boolean sequential, String ruleId) {
        public Evaluation {
            if (action == null) throw new IllegalArgumentException("action must not be null");
            requireText(ruleId, "ruleId");
        }

        public static Evaluation allow(boolean sequential, String ruleId) {
            return new Evaluation(Action.ALLOW, sequential, ruleId);
        }

        public static Evaluation ask(boolean sequential, String ruleId) {
            return new Evaluation(Action.ASK, sequential, ruleId);
        }

        public static Evaluation deny(String ruleId) {
            return new Evaluation(Action.DENY, true, ruleId);
        }
    }

    enum Action { ALLOW, ASK, DENY }

    private static void requireText(String value, String name) {
        if (value == null || value.isBlank()) throw new IllegalArgumentException(name + " must not be blank");
    }
}
